using System;using System.IO;using UnityEngine;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class VerifyHud07Save{
const string Root="Docs/Measurements/2026-10-02-hud-07/";
static OpenWorldSandbox S(){if(!Application.isPlaying||!(Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT")??"").Contains("hud-07"))throw new Exception("Isolated Play required");var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Persistence.Automatic=false;s.Clock.Paused=true;return s;}
public static string Save(){var s=S();s.GetComponent<OpenWorldInput>().Cancel();if(!s.Persistence.Save())throw new Exception(s.Persistence.Status);var data=JObject.Parse(JsonUtility.ToJson(s.Persistence.Capture()));data.Remove("savedUtc");File.WriteAllText(Root+"save-before.json",data.ToString());return "Saved full isolated campaign to disk";}
public static string Reload(){var s=S();s.Persistence.ContinueSaved();return "Requested actual scene reload from isolated disk save";}
public static string Check(){var s=S();if(s.Persistence.Blocked)throw new Exception(s.Persistence.Status);var actual=JObject.Parse(JsonUtility.ToJson(s.Persistence.Capture()));actual.Remove("savedUtc");var expected=JObject.Parse(File.ReadAllText(Root+"save-before.json"));File.WriteAllText(Root+"save-after.json",actual.ToString());var differences=new JArray();foreach(var p in expected.Properties())if(!JToken.DeepEquals(p.Value,actual[p.Name]))differences.Add(p.Name);File.WriteAllText(Root+"save-result.json",new JObject{{"result",differences.Count==0?"PASS":"FAIL"},{"differentFields",differences},{"actualSceneReload",true}}.ToString());if(differences.Count>0)throw new Exception("Different snapshot fields: "+differences);return "Exact full snapshot restored except savedUtc";}}
